void GUI_App::init_app_config()
{
	// Profiles for the alpha are stored into the PrusaSlicer-alpha directory to not mix with the current release.
    SetAppName(SLIC3R_APP_KEY);
//	SetAppName(SLIC3R_APP_KEY "-alpha");
//  SetAppName(SLIC3R_APP_KEY "-beta");
//	SetAppDisplayName(SLIC3R_APP_NAME);

	// Set the Slic3r data directory at the Slic3r XS module.
	// Unix: ~/ .Slic3r
	// Windows : "C:\Users\username\AppData\Roaming\Slic3r" or "C:\Documents and Settings\username\Application Data\Slic3r"
	// Mac : "~/Library/Application Support/Slic3r"

    if (data_dir().empty()) {
        // Orca: check if data_dir folder exists in application folder use it if it exists
        // Note:wxStandardPaths::Get().GetExecutablePath() return following paths
        // Unix: /usr/local/bin/exename
        // Windows: "C:\Programs\AppFolder\exename.exe"
        // Mac: /Applications/exename.app/Contents/MacOS/exename
        // TODO: have no idea what to do with Linux bundles
        auto _app_folder = boost::filesystem::path(wxStandardPaths::Get().GetExecutablePath().ToUTF8().data()).parent_path();
#ifdef __APPLE__
        // On macOS, the executable is inside the .app bundle.
        _app_folder = _app_folder.parent_path().parent_path().parent_path();
#endif
        boost::filesystem::path app_data_dir_path = _app_folder / "data_dir";
        if (boost::filesystem::exists(app_data_dir_path)) {
            set_data_dir(app_data_dir_path.string());
        }
        else{
            boost::filesystem::path data_dir_path;
            #ifndef __linux__
                std::string data_dir = wxStandardPaths::Get().GetUserDataDir().ToUTF8().data();
                //BBS create folder if not exists
                data_dir_path = boost::filesystem::path(data_dir);
                set_data_dir(data_dir);
            #else
                // Since version 2.3, config dir on Linux is in ${XDG_CONFIG_HOME}.
                // https://github.com/prusa3d/PrusaSlicer/issues/2911
                wxString dir;
                if (! wxGetEnv(wxS("XDG_CONFIG_HOME"), &dir) || dir.empty() )
                    dir = wxFileName::GetHomeDir() + wxS("/.config");
                set_data_dir((dir + "/" + GetAppName()).ToUTF8().data());
                data_dir_path = boost::filesystem::path(data_dir());
            #endif
            // Ultra rebrand: the data directory is named after the app key, so it moved when
            // the key did. Copy the old one across before anything creates the new one - this is
            // the only moment at which "the new dir does not exist yet" is still true.
            // Copy, never move: the old install keeps working, which is the real rollback.
            {
                const auto mig = Slic3r::migrate_data_dir(data_dir_path.parent_path().string(),
                                                          data_dir_path.string());
                if (!mig.error.empty())
                    BOOST_LOG_TRIVIAL(error) << "data dir migration failed, starting fresh: " << mig.error;
                else if (mig.ran)
                    g_datadir_migration = mig; // post_init() tells the user what happened
            }
#ifdef _WIN32
            // The embedded browser's profile is keyed on the app name as well (wxStandardPaths'
            // user local data dir + EBWebView): bring the old one across the same way, before
            // any WebView is created, or the Stream tab and the web logins start from nothing.
            {
                const boost::filesystem::path local(wxStandardPaths::Get().GetUserLocalDataDir().ToUTF8().data());
                std::string from;
                if (Slic3r::migrate_webview_profile(local.parent_path().string(), local.string(), &from))
                    BOOST_LOG_TRIVIAL(info) << "browser profile carried over from " << from;
            }
#endif
            if (!boost::filesystem::exists(data_dir_path)){
                boost::filesystem::create_directory(data_dir_path);
            }
        }

        // Change current dirtory of application
        [[maybe_unused]] auto unused_result = chdir(encode_path((Slic3r::data_dir() + "/log").c_str()).c_str());
    } else {
        m_datadir_redefined = true;
    }

    // start log here
    std::time_t       t        = std::time(0);
    std::tm *         now_time = std::localtime(&t);
    std::stringstream buf;
    buf << std::put_time(now_time, "%Y-%m-%d-%H-%M-%S");
    buf << ".log";
    std::string log_filename = buf.str();
#if !BBL_RELEASE_TO_PUBLIC
    set_log_path_and_level(log_filename, 5);
#else
    set_log_path_and_level(log_filename, 3);
#endif
    // Opt-in crash reports carry the last warning/error lines of this log as breadcrumbs. The
    // callee drops everything unless the user has switched crash reports on, and scrubs
    // personal data out of what it keeps (sentry_wrapper/SentryScrub.cpp). Registered only here,
    // next to the file sink: a sink of its own in a console CLI run would switch off Boost.Log's
    // default console output.
    Slic3r::set_log_observer([](int severity, const std::string& message) { Slic3r::sentryAddLogBreadcrumb(severity, message); },
                             3 /* boost::log::trivial::warning */);

    //BBS: remove GCodeViewer as seperate APP logic
	if (!app_config)
        app_config = new AppConfig();
        //app_config = new AppConfig(is_editor() ? AppConfig::EAppMode::Editor : AppConfig::EAppMode::GCodeViewer);

    m_config_corrupted = false;
	// load settings
	m_app_conf_exists = app_config->exists();
	if (m_app_conf_exists) {
        std::string error = app_config->load();
        if (!error.empty()) {
            // Orca: if the config file is corrupted, we will show a error dialog and create a default config file.
            m_config_corrupted = true;

        }
        // Save orig_version here, so its empty if no app_config existed before this run.
        m_last_config_version = app_config->orig_version();//parse_semver_from_ini(app_config->config_path());
    }
    else {
#ifdef _WIN32
        // update associate files from registry information
        if (is_associate_files(L"3mf")) {
            app_config->set("associate_3mf", "true");
        }
        if (is_associate_files(L"stl")) {
            app_config->set("associate_stl", "true");
        }
        if (is_associate_files(L"step") && is_associate_files(L"stp")) {
            app_config->set("associate_step", "true");
        }
#endif // _WIN32
    }
    MixedFilamentManager::set_auto_generate_enabled(app_config->get_bool("auto_generate_gradients"));
    set_logging_level(Slic3r::level_string_to_boost(app_config->get("log_severity_level")));

}

