void GUI_App::request_relaunch()
{
    if (m_relaunch_pending || mainframe == nullptr)
        return;
    m_relaunch_pending = true;
    BOOST_LOG_TRIVIAL(warning) << "Relaunch: requested (process " << wxGetProcessId() << "), closing the main window first";
    CallAfter([this]() { relaunch_when_idle(0); });
}

void GUI_App::relaunch_when_idle(int attempt)
{
    if (mainframe == nullptr) {
        m_relaunch_pending = false;
        return;
    }
    // The dialog that asked is closing; closing the main window under a modal one is asking for trouble.
    if (!mainframe->IsEnabled() && attempt < 40) {
        wxMilliSleep(25);
        CallAfter([this, attempt]() { relaunch_when_idle(attempt + 1); });
        return;
    }
    // The same close File > Quit does: it asks about the unsaved project and can be cancelled.
    if (!mainframe->request_quit(false)) {
        BOOST_LOG_TRIVIAL(warning) << "Relaunch: cancelled, the close was vetoed (unsaved-project prompt, say)";
        m_relaunch_pending = false;
        return;
    }
    // The window is closed and the project dealt with. Start the new process now: it waits for this
    // one to exit (--relaunch-after), so it cannot collide with it, and it is not lost if the
    // teardown that follows hangs or crashes. The window tear-down of a big project can take a
    // while; the new process has its own start-up to do in the meantime.
    BOOST_LOG_TRIVIAL(warning) << "Relaunch: the main window is closed";
    relaunch_now();
}

void GUI_App::relaunch_now()
{
    if (!m_relaunch_pending || m_relaunch_started)
        return;
    if (init_params == nullptr) {
        BOOST_LOG_TRIVIAL(error) << "Relaunch: no command line to start again with, not relaunching";
        return;
    }
    m_relaunch_started = true;
    relaunch_slicer(init_params->argc, init_params->argv, init_params->input_files);
}

void GUI_App::start_remote_access()
{
    RemoteAccess::get().set_hidden(m_hub_managed); // before start(): goes into <pid>.json
    RemoteAccess::get().start();

    // Ultra: SNORCA_LOGIN_LOOPBACK=1 starts the Bambu third-party (Google) login loopback
    // server at startup instead of waiting for the sign-in page's get_localhost_url call.
    // Test-only knob (test_login_loopback.py): it lets the loopback's routes and its bound
    // port be gated without any credentials or a live bambulab page. No effect unless set.
    {
        wxString loopback_env;
        if (wxGetEnv("SNORCA_LOGIN_LOOPBACK", &loopback_env) && loopback_env == "1") {
            BOOST_LOG_TRIVIAL(info) << "SNORCA_LOGIN_LOOPBACK=1: starting the login loopback server at startup";
            start_http_server();
        }
    }

    // Phone access left on last time: bring the hub up with the same link. The token here only
    // seeds a data folder that has never had one - the hub remembers its own and keeps it, so a
    // "New link" made from the tray is not undone by a slicer starting with an older copy.
    // SNORCA_PHONE_ACCESS=<token> does the same without touching the saved settings (agent use).
    wxString    env_token;
    std::string token;
    bool        phone = false;
    if (wxGetEnv("SNORCA_PHONE_ACCESS", &env_token) && !env_token.empty()) {
        token = env_token.ToStdString();
        phone = true;
    } else if (app_config->get("stream_phone_access") == "1") {
        token = app_config->get("stream_phone_token");
        phone = true;
    }
    // The hub (tray icon, camera relays, phone access) starts with the first slicer and stays
    // until quit from its tray menu. Off the GUI thread: spawning it takes a moment.
    //
    // `phone` is only a hint: the hub keeps its own copy of the switch in settings.json and
    // that copy wins, because this app config only learns of a change made from the hub page
    // while the Stream panel is polling - which is how "home mode off" used to come back on
    // at the next slicer start. The hint decides only for a data dir that has never saved the
    // switch (a gate's scratch dir, a first run). A hub that is already running is left as it
    // is: an extra POST /hub/phone from here (batches 65 and 66) made every hidden gate
    // instance crash a second after it registered, from either thread, and the gates that
    // need phone access start their own hub with --hub-phone anyway.
    std::thread([token, phone]() { RemoteHub::ensure_running(token, phone); }).detach();
}

void GUI_App::recreate_GUI(const wxString &msg_name)
{
    BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << "recreate_GUI enter";
    m_is_recreating_gui = true;

    update_http_extra_header();

    mainframe->shutdown(true);

    ProgressDialog dlg(msg_name, msg_name, 100, nullptr, wxPD_AUTO_HIDE);
    dlg.Pulse();
    dlg.Update(10, _L("Rebuild") + dots);

    MainFrame *old_main_frame = mainframe;
    struct ClientData : wxClientData
    {
        ~ClientData() { release_window_pools(); }
    };
    old_main_frame->SetClientObject(new ClientData);

    switch_window_pools();
    mainframe = new MainFrame();

    // The update dialog is a child of the old main frame and is destroyed with it below; a
    // kept pointer would dangle and crash the next Help > Check for Update.
    m_updateDialog = nullptr;
    if (!m_updateDialog) {
        m_updateDialog = new UpdateVersionDialog(mainframe);
        m_updateDialog->Hide();
        m_updateDialog->Bind(EVT_DOWN_URL_PACK, [this](wxCommandEvent& event) {
            auto downloadUlr = m_updateDialog->getUrl();
            wxLaunchDefaultBrowser(downloadUlr);
        });
    }
    if (is_editor())
        // hide settings tabs after first Layout
        mainframe->select_tab(size_t(MainFrame::tp3DEditor));
    // Propagate model objects to object list.
    sidebar().obj_list()->init();
    SetTopWindow(mainframe);

    dlg.Update(30, _L("Rebuild") + dots);
    old_main_frame->Destroy();

    dlg.Update(80, _L("Loading current presets") + dots);
    m_printhost_job_queue.reset(new PrintHostJobQueue(mainframe->printhost_queue_dlg()));
    load_current_presets();
    if (!m_hub_managed)
        mainframe->Show(true);

    dlg.Update(90, _L("Loading a mode view") + dots);

    obj_list()->set_min_height();
    update_mode();

    // clear previous hms query, so that the hms info can use different language
    if (hms_query)
        hms_query->clear_hms_info();

    //BBS: trigger restore project logic here, and skip confirm
    plater_->trigger_restore_project(1);

    update_publish_status();

    m_is_recreating_gui = false;
    RemoteAccess::reopen_gui_gate(); // closed by mainframe->shutdown(true) above

    //reload home and device page
    sm_disconnect_current_machine(true);
    auto devices = wxGetApp().app_config->get_devices();
    for (auto iter = devices.begin(); iter != devices.end();) {
        if (iter->link_mode == "wan") {
            iter = devices.erase(iter);
        } else {
            iter++;
        }
    }

    bool use_new_connection = wxGetApp().app_config->get("use_new_connect") == "true";
    const auto& edit_preset = preset_bundle->printers.get_edited_preset();

    auto printer_config    = wxGetApp().preset_bundle->printers.get_edited_preset().config;
    auto printer_model_opt = printer_config.option<ConfigOptionString>("printer_model");
    bool is_snapmaker_u1   = false;
    if (printer_model_opt) {
        std::string printer_model = printer_model_opt->value;
        is_snapmaker_u1           = boost::icontains(printer_model, "Snapmaker") && boost::icontains(printer_model, "U1");
    }

    if (!preset_bundle->is_bbl_vendor()) {
        if (is_snapmaker_u1) {
            wxString url      = wxString::FromUTF8(page_url("/web/flutter_web/index.html?path=2"));
            auto     real_url = wxGetApp().get_international_url(url);
            mainframe->load_printer_url(real_url);
        } else {
            auto url = wxString::FromUTF8(page_url("/web/orca/missing_connection.html"));
            mainframe->load_printer_url(url);
        }
    }

    wxGetApp().device_card_notify(devices);

    BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << "recreate_GUI exit";
}

