void GUI_App::handle_http_error(unsigned int status, std::string body)
{
    // tips body size must less than 1024
    auto evt = new wxCommandEvent(EVT_HTTP_ERROR);
    evt->SetInt(status);
    evt->SetString(wxString(body));
    wxQueueEvent(this, evt);
}

void GUI_App::on_http_error(wxCommandEvent &evt)
{
    int status = evt.GetInt();

    int code = 0;
    std::string error;
    wxString result;
    if (status >= 400 && status < 500) {
        try {
        auto evt_str = evt.GetString();
        if (!evt_str.empty()) {
            json j = json::parse(evt_str.utf8_string());
            if (j.contains("code")) {
                if (!j["code"].is_null())
                    code = j["code"].get<int>();
            }
            if (j.contains("error"))
                if (!j["error"].is_null())
                    error = j["error"].get<std::string>();
        }
        } catch (...) {}
    }

    // Version limit
    if (code == HttpErrorVersionLimited) {
        MessageDialog msg_dlg(nullptr, _L("The version of EdgeSlicer is too low and needs to be updated to the latest version before it can be used normally"), "", wxAPPLY | wxOK);
        if (msg_dlg.ShowModal() == wxOK) {
        }

    }

    // request login
    if (status == 401) {
        if (m_agent) {
            if (m_agent->is_user_login()) {
                this->request_user_logout();

                if (!m_show_http_errpr_msgdlg) {
                    MessageDialog msg_dlg(nullptr, _L("Login information expired. Please login again."), "", wxAPPLY | wxOK);
                    m_show_http_errpr_msgdlg = true;
                    auto modal_result = msg_dlg.ShowModal();
                    if (modal_result == wxOK || modal_result == wxCLOSE) {
                        m_show_http_errpr_msgdlg = false;
                        return;
                    }
                }
            }
        }
        return;
    }
}

void GUI_App::enable_user_preset_folder(bool enable)
{
    // Ultra: keep the user's preset library in the shared "default" folder regardless of
    // Bambu login. Upstream switches to a per-account folder on login, which hides every
    // preset the user made while logged out (printer/process/filament) and reads as data
    // loss. Login should affect cloud devices only, not the local preset library.
    (void) enable;
    app_config->set("preset_folder", "");
    GUI::wxGetApp().preset_bundle->update_user_presets_directory(DEFAULT_USER_FOLDER_NAME);
}

void GUI_App::sync_bambu_user_presets(bool force_refresh)
{
    if (!app_config || !app_config->get_bool("sync_bambu_user_presets"))
        return;
    std::string uid = (m_agent && m_agent->is_user_login()) ? m_agent->get_user_id() : std::string();
    int copied = mirror_bambu_user_presets(uid);
    if (copied > 0 || force_refresh) {
        try {
            preset_bundle->load_user_presets(DEFAULT_USER_FOLDER_NAME, ForwardCompatibilitySubstitutionRule::Enable);
            if (mainframe) mainframe->update_side_preset_ui();
            BOOST_LOG_TRIVIAL(info) << "[preset-mirror] refreshed preset UI after sync (copied=" << copied << ")";
        } catch (const std::exception& e) {
            BOOST_LOG_TRIVIAL(error) << "[preset-mirror] post-sync refresh failed: " << e.what();
        }
    }
}

