void GUI_App::check_new_version_sf(bool show_tips, bool by_user)
{
    (void) show_tips;

    // The startup check respects Preferences > "Check for new versions on startup";
    // Help > Check for Update (by_user) always runs.
    if (!by_user) {
        if (!app_config->get_bool("check_for_updates_on_startup")) {
            BOOST_LOG_TRIVIAL(info) << "new-version check: disabled in preferences";
            return;
        }
        if (m_hub_managed && RemoteAccess::get().hidden()) {
            BOOST_LOG_TRIVIAL(info) << "new-version check: skipped on a hidden instance";
            return;
        }
    }

    std::string update_url = app_config->get_version_upgrade_url();

    // Default: the GitHub release feed of aceRage/EdgeSlicer. A self-hosted server set in the
    // ini ("orca_upgrade_url") replaces it and keeps the Snapmaker JSON schema, handled below.
    if (update_url.empty()) {
        const AppUpdate::Platform platform = AppUpdate::current_platform();
        if (platform == AppUpdate::Platform::LinuxFlatpak) {
            // Flatpak installs are updated by Flathub / the software centre, not by us.
            BOOST_LOG_TRIVIAL(info) << "new-version check: Flatpak build, updates come through Flathub";
            if (by_user) {
                wxCommandEvent* evt = new wxCommandEvent(EVT_SHOW_DIALOG);
                evt->SetString(_L("This is the Flatpak build of EdgeSlicer. New versions arrive through Flathub or your software centre."));
                GUI::wxGetApp().QueueEvent(evt);
            }
            return;
        }

        // Debug aid: EDGESLICER_FAKE_LOCAL_VERSION=2.3.0.0 makes this build compare as that
        // version, so the dialog can be seen without a newer release. Logged loudly.
        // EDGESLICER_FULL_VERSION is Snapmaker_VERSION plus a nightly build's suffix.
        const std::string local_version = AppUpdate::effective_local_version(EDGESLICER_FULL_VERSION);
        if (local_version != EDGESLICER_FULL_VERSION)
            BOOST_LOG_TRIVIAL(warning) << "new-version check: DEBUG EDGESLICER_FAKE_LOCAL_VERSION=" << local_version
                                       << " (real build " << EDGESLICER_FULL_VERSION << ")";

        // Preferences > General > Update channel. Stable reads the latest release; Nightly reads the
        // one "nightly" pre-release (docs/nightly.md).
        const AppUpdate::Channel channel = AppUpdate::channel_from_config(app_config->get("update_channel"));
        const bool               nightly = channel == AppUpdate::Channel::Nightly;
        const char*              api     = nightly ? AppUpdate::GITHUB_NIGHTLY_RELEASE_API : AppUpdate::GITHUB_LATEST_RELEASE_API;

        auto report_failure = [by_user](const std::string& detail) {
            BOOST_LOG_TRIVIAL(warning) << "new-version check failed: " << detail;
            if (!by_user)
                return; // the startup check stays silent
            wxCommandEvent* evt = new wxCommandEvent(EVT_REQUEST_SERVER_FAIL);
            evt->SetString(_L("Could not check for a new version of EdgeSlicer.") + "\n\n" + wxString::FromUTF8(detail));
            GUI::wxGetApp().QueueEvent(evt);
        };

        BOOST_LOG_TRIVIAL(info) << "new-version check (" << AppUpdate::channel_config_value(channel) << " channel): " << api
                                << " (local " << local_version << ")";
        Http::get(api)
            // GitHub requires a User-Agent; it gets "EdgeSlicer/<version>" and nothing else: the
            // process-wide X-BBL-* headers carry a device id and are not for them.
            .clear_headers()
            .header("User-Agent", std::string(SLIC3R_APP_NAME "/") + EDGESLICER_FULL_VERSION)
            .header("Accept", "application/vnd.github+json")
            .header("X-GitHub-Api-Version", "2022-11-28")
            .timeout_connect(TIMEOUT_CONNECT)
            .timeout_max(30)
            .on_error([report_failure, nightly](std::string body, std::string error, unsigned http_status) {
                if (nightly && http_status == 404) {
                    report_failure("No nightly build has been published yet.");
                    return;
                }
                std::string detail = error;
                const AppUpdate::ReleaseInfo parsed = AppUpdate::parse_github_release(body, AppUpdate::current_platform());
                if (!parsed.ok && parsed.error.rfind("GitHub:", 0) == 0)
                    detail = parsed.error; // e.g. "GitHub: API rate limit exceeded ..."
                if (http_status != 0)
                    detail = "HTTP " + std::to_string(http_status) + (detail.empty() ? std::string() : ": " + detail);
                report_failure(detail);
            })
            .on_complete([this, by_user, platform, local_version, report_failure, nightly](std::string body, unsigned http_status) {
                if (http_status != 200) {
                    report_failure("HTTP " + std::to_string(http_status));
                    return;
                }
                const AppUpdate::ReleaseInfo release = nightly ? AppUpdate::parse_github_nightly(body, platform) :
                                                                 AppUpdate::parse_github_release(body, platform);
                const AppUpdate::Verdict verdict = nightly ? AppUpdate::evaluate_nightly(release, local_version) :
                                                             AppUpdate::evaluate(release, local_version);
                switch (verdict) {
                case AppUpdate::Verdict::Invalid:
                    report_failure(release.error.empty() ? "unrecognised answer" : release.error);
                    return;
                case AppUpdate::Verdict::Ignored:
                case AppUpdate::Verdict::UpToDate:
                    BOOST_LOG_TRIVIAL(info) << "new-version check: latest " << release.tag << " (" << release.version_str << ")"
                                            << (!nightly && (release.prerelease || release.draft) ? " (prerelease/draft, ignored)" : "")
                                            << ", nothing newer than " << local_version;
                    if (by_user)
                        this->no_new_version();
                    return;
                case AppUpdate::Verdict::UpdateAvailable: break;
                }
                BOOST_LOG_TRIVIAL(info) << "new-version check: " << release.tag << " (" << release.version_str << ") is newer than "
                                        << local_version << ", download " << release.download_url;
                // Hand the result to the UI thread; the event handler below shows the dialog.
                GUI::wxGetApp().CallAfter([this, release, by_user]() {
                    version_info.force_upgrade = false; // a GitHub release never forces anything
                    version_info.version_str   = release.version_str;
                    version_info.description   = release.notes.text;
                    version_info.url           = release.download_url;
                    s_update_full_notes_url    = release.html_url;
                    wxCommandEvent* evt = new wxCommandEvent(EVT_SLIC3R_VERSION_ONLINE);
                    evt->SetString(version_info.url);
                    if (by_user)
                        evt->SetInt(UPDATE_BY_USER);
                    GUI::wxGetApp().QueueEvent(evt);
                });
            })
            .perform();
        return;
    }

    AppConfig* app_config = wxGetApp().app_config;

    Http::get(update_url)
        .on_error([&, by_user](std::string body, std::string error, unsigned http_status) {
          (void)body;

            wxCommandEvent* evt = new wxCommandEvent(EVT_REQUEST_SERVER_FAIL);
            wxString errorMsg   = wxString::Format(_L("request to server update soft fail with body:%s,error:%s,status:%d"), body,
                                                   error, http_status);
            evt->SetString(errorMsg);
            if(by_user)
                GUI::wxGetApp().QueueEvent(evt);
          BOOST_LOG_TRIVIAL(error) << format("Error getting: `%1%`: HTTP %2%, %3%", "check_new_version_sf", http_status,
                                             error);
        })
        .timeout_connect(TIMEOUT_CONNECT)
        .on_complete([this,by_user](std::string body, unsigned http_status) {
        // Http response OK
        if (http_status != 200) {
            BOOST_LOG_TRIVIAL(error) << format("status not 200 with: `%1%`: HTTP %2%", "check_new_version_sf", http_status);
            return;
          }
        try {
            json jsonObj = json::parse(body);
            auto errCode = jsonObj["code"];
            if (errCode != 200)
                return;

            auto dataObj             = jsonObj.value("data", json::object());
            auto isFullUpgrade       = dataObj.value("is_full_upgrade", true);
            auto isForceUpgrade      = dataObj.value("is_force_upgrade", false);
            version_info.force_upgrade  = isForceUpgrade;

            version_info.version_str = dataObj.value("version", "");
            auto releaseType         = dataObj.value("release_type", "");

            if (releaseType != RELEASE_TYPE_STABLE)
            {
                if (by_user)
                    this->no_new_version();
                return;
            }

            auto platformType        = dataObj.value("platform_type", "");
            int  fileSize            = 0;
            std::string fileMd5             = "";
            std::string fileSha256          = "";
            std::string reservedData        = "";
            std::string reservedData2        = "";

            // win x86_x64,  mac arm/x86_x64  universal
            auto fullObj = dataObj.value("full", json::object());
            auto defaultObj = fullObj.value("default", json::object());
            auto armObj     = fullObj.value("arm", json::object());
            auto intelObj   = fullObj.value("intel", json::object());
            version_info.description = fullObj.value("file_describe", "");

            if (platformType == "win") {
                fileSize   = defaultObj.value("file_size", 0);
                fileMd5    = defaultObj.value("file_md5", "");
                fileSha256 = defaultObj.value("file_sha256", "");
                version_info.url         = defaultObj.value("file_url", "");

                reservedData             = defaultObj.value("reserved_1", "");
                reservedData2            = defaultObj.value("reserved_2", "");
            }
            else if (platformType == "mac")
            {
                bool isArm64 = false;
#if defined(__aarch64__) || defined(__arm64__) || defined(_M_ARM64)
                isArm64 = true;
#else
                isArm64 = false;
#endif
                json platformObj = defaultObj;
                if (isArm64) {
                    if (!armObj.empty()) {
                        platformObj = armObj;
                    }
                }
                else
                {
                    if (!intelObj.empty()) {
                        platformObj = intelObj;
                    }
                }

                fileSize         = platformObj.value("file_size", 0);
                fileMd5          = platformObj.value("file_md5", "");
                fileSha256       = platformObj.value("file_sha256", "");
                version_info.url = platformObj.value("file_url", "");

                reservedData  = platformObj.value("reserved_1", "");
                reservedData2 = platformObj.value("reserved_2", "");

            }
            else
            {
                BOOST_LOG_TRIVIAL(warning) << "don't support linux upgrade";
                return;
            }

            // Same four-part comparison as the GitHub path (Semver folds a fourth part into
            // patch*100, which misorders 2.3.9 against 2.3.8.5).
            const AppUpdate::Version current_version = AppUpdate::parse_version(AppUpdate::effective_local_version(Snapmaker_VERSION));
            const AppUpdate::Version server_version  = AppUpdate::parse_version(version_info.version_str);

            if (!server_version.valid || AppUpdate::compare_versions(current_version, server_version) >= 0) {
                if(by_user)
                    this->no_new_version();
                return;
            }

            if (isForceUpgrade)
            {
                wxGetApp().app_config->set_bool("force_upgrade", version_info.force_upgrade);
                wxGetApp().app_config->set("upgrade", "force_upgrade", true);
                wxGetApp().app_config->set("upgrade", "description", version_info.description);
                wxGetApp().app_config->set("upgrade", "version", version_info.version_str);
                wxGetApp().app_config->set("upgrade", "url", version_info.url);
                GUI::wxGetApp().enter_force_upgrade();
                return;
            }

            s_update_full_notes_url.clear(); // the self-hosted schema has no release page
            wxCommandEvent* evt = new wxCommandEvent(EVT_SLIC3R_VERSION_ONLINE);
            evt->SetString(version_info.url);
            if (by_user)
                evt->SetInt(UPDATE_BY_USER);
            GUI::wxGetApp().QueueEvent(evt);
        } catch (const std::exception& ex) {
            std::string errorMsg = ex.what();
            BOOST_LOG_TRIVIAL(fatal) << "request server soft update data error:" << errorMsg;
          }
        })
        .perform();
}
