bool GUI_App::check_print_host_queue()
{
    wxString dirty;
    std::vector<std::pair<std::string, std::string>> jobs;
    // Get ongoing jobs from dialog
    mainframe->m_printhost_queue_dlg->get_active_jobs(jobs);
    if (jobs.empty())
        return true;
    // Show dialog
    wxString job_string = wxString();
    for (const auto& job : jobs) {
        job_string += format_wxstr("   %1% : %2% \n", job.first, job.second);
    }
    wxString message;
    message += _(L("The uploads are still ongoing")) + ":\n\n" + job_string +"\n" + _(L("Stop them and continue anyway?"));
    //wxMessageDialog dialog(mainframe,
    MessageDialog dialog(mainframe,
        message,
        wxString(SLIC3R_APP_NAME) + " - " + _(L("Ongoing uploads")),
        wxICON_QUESTION | wxYES_NO | wxNO_DEFAULT);
    if (dialog.ShowModal() == wxID_YES)
        return true;

    // TODO: If already shown, bring forward
    mainframe->m_printhost_queue_dlg->Show();
    return false;
}

bool GUI_App::checked_tab(Tab* tab)
{
    bool ret = true;
    if (find(tabs_list.begin(), tabs_list.end(), tab) == tabs_list.end() &&
        find(model_tabs_list.begin(), model_tabs_list.end(), tab) == model_tabs_list.end())
        ret = false;
    return ret;
}

// Update UI / Tabs to reflect changes in the currently loaded presets
//BBS: add preset combo box re-activate logic
void GUI_App::load_current_presets(bool active_preset_combox/*= false*/, bool check_printer_presets_ /*= true*/)
{
    // check printer_presets for the containing information about "Print Host upload"
    // and create physical printer from it, if any exists
    if (check_printer_presets_)
        check_printer_presets();

    PrinterTechnology printer_technology = preset_bundle->printers.get_edited_preset().printer_technology();
	this->plater()->set_printer_technology(printer_technology);
    for (Tab *tab : tabs_list)
		if (tab->supports_printer_technology(printer_technology)) {
			if (tab->type() == Preset::TYPE_PRINTER) {
				static_cast<TabPrinter*>(tab)->update_pages();
				// Mark the plater to update print bed by tab->load_current_preset() from Plater::on_config_change().
				this->plater()->force_print_bed_update();
			}
			tab->load_current_preset();
			//BBS: add preset combox re-active logic
			if (active_preset_combox)
				tab->reactive_preset_combo_box();
		}
    // BBS: model config
    for (Tab *tab : model_tabs_list)
		if (tab->supports_printer_technology(printer_technology)) {
            tab->rebuild_page_tree();
        }

    if (printer_technology == ptFFF && preset_bundle != nullptr) {
        static const t_config_option_keys mixed_project_option_keys = {
            "mixed_filament_gradient_mode",
            "mixed_filament_height_lower_bound",
            "mixed_filament_height_upper_bound",
            "mixed_filament_advanced_dithering",
            "mixed_filament_component_bias_enabled",
            "mixed_filament_surface_indentation",
            "mixed_filament_region_collapse",
            "mixed_color_layer_height_a",
            "mixed_color_layer_height_b",
            "dithering_z_step_size",
            "dithering_local_z_mode",
            "dithering_local_z_whole_objects",
            "dithering_local_z_infill",
            "dithering_local_z_direct_multicolor",
            "dithering_step_painted_zones_only",
            "mixed_filament_pointillism_pixel_size",
            "mixed_filament_pointillism_line_gap",
            "mixed_filament_definitions",
            "mixed_filament_auto_gradient_choice",
            "mixed_filament_auto_gradient_physical_count"
        };

        // Keep the Mixed Filaments sidebar state in sync when presets are reloaded
        // programmatically (for example after New Project). These options are also
        // mirrored on manual edits in Tab::on_value_change(), but that path does
        // not run when the current preset is simply reloaded.
        preset_bundle->project_config.apply_only(
            preset_bundle->prints.get_edited_preset().config,
            mixed_project_option_keys,
            true);

        if (plater_ != nullptr)
            sidebar().update_mixed_filament_panel(false);
    }
    // Sidebar nozzle diameter combos depend on visible printer variants; rebuild after import / preset reload.
    if (plater() != nullptr)
        plater()->sidebar().update_nozzle_settings();

    //load_filament_hot_bed_nozzle_relations();
}

