#ifdef __WXMSW__
static bool set_into_win_registry(HKEY hkeyHive, const wchar_t* pszVar, const wchar_t* pszValue)
{
    // see as reference: https://stackoverflow.com/questions/20245262/c-program-needs-an-file-association
    wchar_t szValueCurrent[1000];
    DWORD dwType;
    DWORD dwSize = sizeof(szValueCurrent);

    int iRC = ::RegGetValueW(hkeyHive, pszVar, nullptr, RRF_RT_ANY, &dwType, szValueCurrent, &dwSize);

    bool bDidntExist = iRC == ERROR_FILE_NOT_FOUND;

    if ((iRC != ERROR_SUCCESS) && !bDidntExist)
        // an error occurred
        return false;

    if (!bDidntExist) {
        if (dwType != REG_SZ)
            // invalid type
            return false;

        if (::wcscmp(szValueCurrent, pszValue) == 0)
            // value already set
            return false;
    }

    DWORD dwDisposition;
    HKEY hkey;
    iRC = ::RegCreateKeyExW(hkeyHive, pszVar, 0, 0, 0, KEY_ALL_ACCESS, nullptr, &hkey, &dwDisposition);
    bool ret = false;
    if (iRC == ERROR_SUCCESS) {
        iRC = ::RegSetValueExW(hkey, L"", 0, REG_SZ, (BYTE*)pszValue, (::wcslen(pszValue) + 1) * sizeof(wchar_t));
        if (iRC == ERROR_SUCCESS)
            ret = true;
    }

    RegCloseKey(hkey);
    return ret;
}

static bool del_win_registry(HKEY hkeyHive, const wchar_t *pszVar, const wchar_t *pszValue)
{
    wchar_t szValueCurrent[1000];
    DWORD   dwType;
    DWORD   dwSize = sizeof(szValueCurrent);

    int iRC = ::RegGetValueW(hkeyHive, pszVar, nullptr, RRF_RT_ANY, &dwType, szValueCurrent, &dwSize);

    bool bDidntExist = iRC == ERROR_FILE_NOT_FOUND;

    if ((iRC != ERROR_SUCCESS) && !bDidntExist)
        return false;

    if (!bDidntExist) {
        iRC      = ::RegDeleteKeyExW(hkeyHive, pszVar, KEY_ALL_ACCESS, 0);
        if (iRC == ERROR_SUCCESS) {
            return true;
        }
    }

    return false;
}

#endif // __WXMSW__

void GUI_App::associate_files(std::wstring extend)
{
#ifdef WIN32
    wchar_t app_path[MAX_PATH];
    ::GetModuleFileNameW(nullptr, app_path, sizeof(app_path));

    std::wstring prog_path = L"\"" + std::wstring(app_path) + L"\"";
    // Our own ProgID. The inherited " Orca.Slicer.1" (leading space and all) is shared with
    // OrcaSlicer and Snapmaker Orca, so associating files here re-pointed theirs as well.
    // A user upgrading has to tick the association preference once more.
    std::wstring prog_id = L"EdgeSlicer.Model.1";
    std::wstring prog_desc = L"EdgeSlicer";
    std::wstring prog_command = prog_path + L" \"%1\"";
    std::wstring reg_base = L"Software\\Classes";
    std::wstring reg_extension = reg_base + L"\\." + extend;
    std::wstring reg_prog_id = reg_base + L"\\" + prog_id;
    std::wstring reg_prog_id_command = reg_prog_id + L"\\Shell\\Open\\Command";

    bool is_new = false;
    is_new |= set_into_win_registry(HKEY_CURRENT_USER, reg_extension.c_str(), prog_id.c_str());
    is_new |= set_into_win_registry(HKEY_CURRENT_USER, reg_prog_id.c_str(), prog_desc.c_str());
    is_new |= set_into_win_registry(HKEY_CURRENT_USER, reg_prog_id_command.c_str(), prog_command.c_str());
    if (is_new)
        // notify Windows only when any of the values gets changed
        ::SHChangeNotify(SHCNE_ASSOCCHANGED, SHCNF_IDLIST, nullptr, nullptr);
#endif // WIN32
}

void GUI_App::disassociate_files(std::wstring extend)
{
#ifdef WIN32
    wchar_t app_path[MAX_PATH];
    ::GetModuleFileNameW(nullptr, app_path, sizeof(app_path));

    std::wstring prog_path = L"\"" + std::wstring(app_path) + L"\"";
    // Our own ProgID. The inherited " Orca.Slicer.1" (leading space and all) is shared with
    // OrcaSlicer and Snapmaker Orca, so associating files here re-pointed theirs as well.
    // A user upgrading has to tick the association preference once more.
    std::wstring prog_id = L"EdgeSlicer.Model.1";
    std::wstring prog_desc = L"EdgeSlicer";
    std::wstring prog_command = prog_path + L" \"%1\"";
    std::wstring reg_base = L"Software\\Classes";
    std::wstring reg_extension = reg_base + L"\\." + extend;
    std::wstring reg_prog_id = reg_base + L"\\" + prog_id;
    std::wstring reg_prog_id_command = reg_prog_id + L"\\Shell\\Open\\Command";

    bool is_new = false;
    is_new |= del_win_registry(HKEY_CURRENT_USER, reg_extension.c_str(), prog_id.c_str());

    bool is_associate_3mf  = app_config->get("associate_3mf") == "true";
    bool is_associate_stl  = app_config->get("associate_stl") == "true";
    bool is_associate_step = app_config->get("associate_step") == "true";
    if (!is_associate_3mf && !is_associate_stl && !is_associate_step)
    {
        is_new |= del_win_registry(HKEY_CURRENT_USER, reg_prog_id.c_str(), prog_desc.c_str());
        is_new |= del_win_registry(HKEY_CURRENT_USER, reg_prog_id_command.c_str(), prog_command.c_str());
    }

    if (is_new)
       ::SHChangeNotify(SHCNE_ASSOCCHANGED, SHCNF_IDLIST, nullptr, nullptr);
#endif // WIN32
}

bool GUI_App::check_url_association(std::wstring url_prefix, std::wstring& reg_bin)
{
    reg_bin = L"";
#ifdef WIN32
    const wxString cmd_path = "Software\\Classes\\" + wxString(url_prefix) + "\\shell\\open\\command";
    wxRegKey      key_cu(wxRegKey::HKCU, cmd_path);
    wxRegKey      key_lm(wxRegKey::HKLM, cmd_path);
    if (key_cu.Exists())
        reg_bin = key_cu.QueryDefaultValue().ToStdWstring();
    else if (key_lm.Exists())
        reg_bin = key_lm.QueryDefaultValue().ToStdWstring();
    else
        return false;

    boost::filesystem::path binary_path(boost::filesystem::canonical(boost::dll::program_location()));
    std::wstring key_string = L"\"" + binary_path.wstring() + L"\" \"%1\"";
    return key_string == reg_bin;
#else
    return false;
#endif // WIN32
}

#ifdef WIN32
// Rewrite one HKCU "shell open command" default value if -- and only if -- it names an
// executable that no longer exists. Returns true when it actually changed something.
static bool repair_one_stale_command(const wchar_t* key_path, const std::wstring& want_command)
{
    wxRegKey key(wxRegKey::HKCU, key_path);
    if (! key.Exists())
        return false;
    const std::wstring current = key.QueryDefaultValue().ToStdWstring();
    if (current.empty() || current == want_command)
        return false;
    // Only the quoted-path form is ours to interpret; anything else the user or another
    // installer wrote stays untouched.
    if (current.front() != L'"')
        return false;
    const size_t close = current.find(L'"', 1);
    if (close == std::wstring::npos || close < 2)
        return false;
    const std::wstring exe = current.substr(1, close - 1);
    boost::system::error_code ec;
    if (boost::filesystem::exists(boost::filesystem::path(exe), ec))
        return false;   // still a real file -- not stale, leave it alone
    BOOST_LOG_TRIVIAL(info) << "association self-heal: " << into_u8(wxString(key_path))
                            << " pointed at a missing executable, rewriting it";
    key = wxString(want_command);
    return true;
}
#endif // WIN32

// The file associations and the edgeslicer:// scheme are written into HKCU with the
// full path of the running exe. Renaming the binary (snapmaker-orca.exe -> EdgeSlicer.exe)
// leaves those commands pointing at a file that is gone, so a double-clicked .3mf or a
// link gets a "Windows cannot find" box and nothing repairs it until the user re-ticks
// the association preference. Fix them in place at startup, silently, once.
void GUI_App::repair_stale_associations()
{
#ifdef WIN32
    wchar_t app_path[MAX_PATH] = { 0 };
    if (::GetModuleFileNameW(nullptr, app_path, MAX_PATH) == 0)
        return;
    const std::wstring want = std::wstring(L"\"") + app_path + L"\" \"%1\"";

    // Both file classes (associate_files writes one ProgID for models and g-code alike;
    // the second name is listed defensively in case that ever splits) and the URL scheme.
    static const wchar_t* const key_paths[] = {
        L"Software\\Classes\\EdgeSlicer.Model.1\\Shell\\Open\\Command",
        L"Software\\Classes\\EdgeSlicer.GCode.1\\Shell\\Open\\Command",
        L"Software\\Classes\\edgeslicer\\shell\\open\\command",
    };

    bool changed = false;
    for (const wchar_t* path : key_paths)
        changed |= repair_one_stale_command(path, want);
    if (changed)
        ::SHChangeNotify(SHCNE_ASSOCCHANGED, SHCNF_IDLIST, nullptr, nullptr);
#endif // WIN32
}

void GUI_App::associate_url(std::wstring url_prefix)
{
#ifdef WIN32
    boost::filesystem::path binary_path(boost::filesystem::canonical(boost::dll::program_location()));
    // the path to binary needs to be correctly saved in string with respect to localized characters
    wxString wbinary = wxString::FromUTF8(binary_path.string());
    std::string binary_string = (boost::format("%1%") % wbinary).str();
    BOOST_LOG_TRIVIAL(info) << "Downloader registration: Path of binary: " << binary_string;

    std::string key_string = "\"" + binary_string + "\" \"%1\"";

    wxRegKey key_first(wxRegKey::HKCU, "Software\\Classes\\" + url_prefix);
    wxRegKey key_full(wxRegKey::HKCU, "Software\\Classes\\" + url_prefix + "\\shell\\open\\command");
    if (!key_first.Exists()) {
        key_first.Create(false);
    }
    key_first.SetValue("URL Protocol", "");

    if (!key_full.Exists()) {
        key_full.Create(false);
    }
    key_full = key_string;
#elif defined(__linux__) && defined(SLIC3R_DESKTOP_INTEGRATION)
    DesktopIntegrationDialog::perform_downloader_desktop_integration(into_u8(url_prefix));
#endif // WIN32
}

void GUI_App::disassociate_url(std::wstring url_prefix)
{
#ifdef WIN32
    wxRegKey key_full(wxRegKey::HKCU, "Software\\Classes\\" + url_prefix + "\\shell\\open\\command");
    if (!key_full.Exists()) {
        return;
    }
    key_full = "";
#endif // WIN32
}


